package business.control;

import infra.InfraException;
import business.model.Curso;
import business.model.Questionario;
import java.util.Map;
import javax.swing.JOptionPane;

public class AdminManager {

    private CursoManager cursoManager;
    private QuestionarioManager questionarioManager;

    public AdminManager() throws InfraException {
        // Inicializa os managers dependendo dos arquivos de persistência
        this.cursoManager = new CursoManager();
        this.questionarioManager = new QuestionarioManager();
    }

    // ===============================================
    // MÉTODOS PARA GERENCIAR CURSOS
    // ===============================================

    public void menuCursos() {
        while (true) {
            String choice = JOptionPane.showInputDialog("--- GERENCIAMENTO DE CURSOS ---\n1. Adicionar Curso\n2. Visualizar Cursos\n3. Remover Curso\n4. Voltar ao Menu Principal Admin");
            if (choice == null) return;

            try {
                int option = Integer.parseInt(choice);
                switch (option) {
                    case 1:
                        adicionarCursoInterface();
                        break;
                    case 2:
                        visualizarCursosInterface();
                        break;
                    case 3:
                        removerCursoInterface();
                        break;
                    case 4:
                        return; // Volta para o menu Admin
                    default:
                        JOptionPane.showMessageDialog(null, "Opção inválida!");
                }
            } catch (NumberFormatException e) {
                JOptionPane.showMessageDialog(null, "Por favor, insira um número válido.");
            } catch (InfraException e) {
                JOptionPane.showMessageDialog(null, "Erro ao acessar dados de cursos: " + e.getMessage());
            }
        }
    }

    private void adicionarCursoInterface() {
        String nome = JOptionPane.showInputDialog("Nome do Curso:");
        String cidade = JOptionPane.showInputDialog("Cidade do Curso:");
        String centro = JOptionPane.showInputDialog("Centro/Localização do Curso:");

        if (nome != null && cidade != null && centro != null) {
            // Args: {nome, cidade, centro}
            cursoManager.adicionarCurso(new String[]{nome, cidade, centro});
            JOptionPane.showMessageDialog(null, "Curso adicionado com sucesso!");
        } else {
            JOptionPane.showMessageDialog(null, "Operação cancelada.");
        }
    }

    private void visualizarCursosInterface() throws InfraException {
        Map<String, Curso> cursos = cursoManager.getCursos();
