        StringBuilder sb = new StringBuilder("--- LISTA DE CURSOS ---\n");
        for (Curso curso : cursos.values()) {
            sb.append(curso.toString()).append("\n");
        }
        JOptionPane.showMessageDialog(null, sb.toString(), "Cursos Cadastrados", JOptionPane.INFORMATION_MESSAGE);
    }

    private void removerCursoInterface() {
        String nomeParaRemover = JOptionPane.showInputDialog("Digite o NOME COMPLETO do curso que deseja remover:");
        if (nomeParaRemover != null && !nomeParaRemover.trim().isEmpty()) {
            try {
                cursoManager.removerCurso(nomeParaRemover);
                JOptionPane.showMessageDialog(null, "Curso removido com sucesso!");
